open('todo.py','w').write('''import json,os
class Todo:
    def __init__(self,path):
        self.path=path
        self.items=json.load(open(path)) if os.path.exists(path) else []
    def save(self):
        json.dump(self.items,open(self.path,"w"))
    def add(self,text):
        self.items.append({"text":text,"done":False}); self.save()
    def done(self,i):
        self.items[i]["done"]=True; self.save()
    def list(self): return self.items
''')
